{
  "investigate": [
    {
      "tool": "logs",
      "service": "order-service",
      "level": "ERROR",
      "contains": "database timeout: connection pool exhausted",
      "why": "Check if order-service is also experiencing database pool exhaustion to confirm the issue is widespread and not just in payment-service and worker."
    },
    {
      "tool": "sql",
      "query": "SELECT service, COUNT(*) as open_connections FROM db_sessions WHERE open = 1 GROUP BY service;",
      "why": "Identify which services are holding open database connections to understand the source of pool exhaustion."
    }
  ],
  "hypotheses": [
    {
      "service": "database",
      "kind": "resource_exhaustion",
      "mechanism": "The database connection pool is exhausted, causing timeouts for dependent services like payment-service and worker.",
      "supporting": ["E2", "E7", "E8", "E9"],
      "refuting": ["E12"],
      "explains": ["M2_error_burst", "M3_dead_letters", "M4_db_pool_pressure"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "database"
          }
        }
      ]
    }
  ],
  "summary": "Database connection pool exhaustion is causing timeouts in payment-service and worker, leading to errors and dead letters."
}
